public class GreetServletSim {
    void init() {
        System.out.println("init() called once");
    }
    void service(String name, int marks) {
        doGet(name, marks);
    }
    void doGet(String name, int marks) {
        System.out.println(name + " scored " + marks);
    }
    void destroy() {
        System.out.println("destroy() called once");
    }
    public static void main(String[] args) {
        GreetServletSim s = new GreetServletSim();
        s.init();
        int calls = 0;
        for (int i = 0; i < 3; i++) {
            s.service("Anu", 78);
            calls++;
        }
        System.out.println("service() calls = " + calls);
        s.destroy();
    }
}
